3	import (
4		"encoding/json"
5		"time"
6	)
7	
8	// Date is a calendar day with no time of day. The zero Date means "no due date" and is
9	// written to JSON as an empty string so clients never see 0001-01-01.
10	type Date struct{ time.Time }
11	
12	const dateLayout = "2006-01-02"
13	
14	func ParseDate(s string) (Date, error) {
15		if s == "" {
16			return Date{}, nil
17		}
18		t, err := time.Parse(dateLayout, s)
19		if err != nil {
20			return Date{}, err
21		}
22		return Date{t}, nil
23	}
24	
25	func (d Date) MarshalJSON() ([]byte, error) {
26		if d.IsZero() {
27			return json.Marshal("")
28		}
29		return json.Marshal(d.Format(dateLayout))
30	}
31	
32	func (d *Date) UnmarshalJSON(b []byte) error {
33		var s string
34		if err := json.Unmarshal(b, &s); err != nil {
35			return err
36		}
37		p, err := ParseDate(s)
38		if err != nil {
39			return err
40		}
41		*d = p
42		return nil
43	}
